import java.util.ArrayList;
import java.util.List;

class RodCuttingSolver implements Solver {

    private static class BestCut {
        final int length;
        final int revenue;

        BestCut(int length, int revenue) {
            this.length = length;
            this.revenue = revenue;
        }
    }

    @Override
    public RodCuttingSolution solve(RodCuttingProblem problem) {
        int n = problem.rodLength();
        Prices prices = problem.prices();
        int[] revenue = new int[n + 1];
        int[] cutChoice = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            BestCut best = findBestCut(i, prices, revenue);
            revenue[i] = best.revenue;
            cutChoice[i] = best.length;
        }

        return new RodCuttingSolution(revenue[n], reconstructCuts(n, cutChoice));
    }

    private BestCut findBestCut(int rodLength, Prices prices, int[] revenue) {
        int bestRevenue = prices.priceFor(1) + revenue[rodLength - 1];
        int bestCutLength = 1;

        for (int cutLength = 2; cutLength <= rodLength; cutLength++) {
            int candidate = prices.priceFor(cutLength) + revenue[rodLength - cutLength];
            if (candidate > bestRevenue) {
                bestRevenue = candidate;
                bestCutLength = cutLength;
            }
        }

        return new BestCut(bestCutLength, bestRevenue);
    }

    private List<Integer> reconstructCuts(int n, int[] cutChoice) {
        List<Integer> cuts = new ArrayList<>();
        int remaining = n;
        while (remaining > 0) {
            int cut = cutChoice[remaining];
            cuts.add(cut);
            remaining -= cut;
        }
        return cuts;
    }
}

